SELECT
	aftersales.self_delivery_operator_id AS selfDeliveryOperatorId,
	COUNT(aftersales.order_id) AS aftersalesCount,
	SUM(aftersales.refund_fee) AS refundFeeCount
FROM aftersales
LEFT JOIN aftersales_refund ON aftersales.aftersales_bn = aftersales_refund.aftersales_bn
WHERE aftersales.aftersales_status = 2
	AND aftersales.company_id = #{companyId}
	AND aftersales_refund.refund_success_time >= #{startEpoch}
	AND aftersales_refund.refund_success_time <= #{endEpoch}

	AND aftersales.self_delivery_operator_id IN

		#{oid}



	AND aftersales.distributor_id IN

		#{did}


GROUP BY aftersales.self_delivery_operator_id

